"""Load actual saves generated by pre-v40 main in an independent process."""
import json,sys,subprocess
from pathlib import Path
from moonpa_savegame import create_save,load_save
root=Path(__file__).resolve().parents[1]
for file in sorted(Path(sys.argv[1]).glob('*.json')):
    item=json.loads(file.read_text(encoding='utf8'));s=item['snapshot'];c=load_save(item['save']);g=c.guild;w=c.world
    assert (g.name,c.season,c.week,c.phase,g.cash)==(s['name'],s['season'],s['week'],s['phase'],s['cash']),file
    roster=[dict(id=f.fid,name=f.name,portrait=f.portrait_key,wage=f.wage,end=f.contract_end,
        ca=f.ca,pa=f.pa,injured=f.injured,arts=f.development.secret_arts) for f in g.fighters]
    assert roster==s['roster'],file
    assert [z.owner for z in w.zones]==s['owners'],file
    assert repr(w.rng.getstate())==s['rng'],file
    assert c.overview()['player_journal']['difference']==0,file
    assert not c.overview()['missions_enabled'],file
    if file.stem=='expedition':
        assert s['away'] and not w.away(g.gid),file
    if file.stem=='group':
        assert json.loads(json.dumps(c.group_play,ensure_ascii=False))==s['group'],file
        cfg=c.group_play
        js="""import fs from 'node:fs';import {Arena} from './group-engine.mjs';const c=JSON.parse(fs.readFileSync(0,'utf8'));console.log(JSON.stringify(Arena.settle(c,{lineup:c.team,captain:c.captain,deputy:c.deputy,arts:c.chosenArts})));"""
        result=json.loads(subprocess.run(['node','--input-type=module','-e',js],input=json.dumps(cfg),text=True,capture_output=True,check=True,cwd=root).stdout)
        c.finish_group(cfg['match'],result)
        assert c.week==2,file
        assert c.overview()['player_journal']['difference']==0,file
    if file.stem=='ready':
        c.submit_week(c.season,c.week,{})
        assert c.week==s['week']+1,file
        assert c.overview()['player_journal']['difference']==0,file
    restored=load_save(create_save(c))
    assert restored.overview()==c.overview(),file
    print('V40_LEGACY_PASS',file.stem,flush=True)
